pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26));
        vm.assume(caller != address(0x000000000000000000000000000000000000dEaD));
        vm.assume(caller.code.length == 0);
        vm.prank(address(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26));
        c.DrugDealer();
        vm.prank(caller);
        vm.expectRevert();
        c.DrugDealer();
    }
}

